def second_largest(numbers):
  """Returns the second largest number in a list."""
  if len(numbers) < 2:
    return None
  unique_numbers = sorted(list(set(numbers)))
  if len(unique_numbers) < 2:
    return unique_numbers[0]
  return unique_numbers[-2]
